import bisect
def length_of_lis(nums):
    tails = []
    for x in nums:
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)
result = length_of_lis([10, 9, 2, 5, 3, 7, 101, 18])
print(f'LIS Length: {result}')

from collections import deque
def topo_sort(num_nodes, edges):
    in_degree = {i: 0 for i in range(num_nodes)}
    adj = {i: [] for i in range(num_nodes)}
    for u, v in edges:
        adj[u].append(v)
        in_degree[v] += 1
    q = deque([n for n, d in in_degree.items() if d == 0])
    order = []
    while q:
        curr = q.popleft()
        order.append(curr)
        for nxt in adj[curr]:
            in_degree[nxt] -= 1
            if in_degree[nxt] == 0:
                q.append(nxt)
    return order
order = topo_sort(4, [[0, 1], [0, 2], [1, 3], [2, 3]])
result = (order[0] == 0 and order[-1] == 3 and len(order) == 4)
print(f'Topological Sort Valid: {result}, Order: {order}')

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False
class Trie:
    def __init__(self):
        self.root = TrieNode()
    def insert(self, word):
        curr = self.root
        for ch in word:
            if ch not in curr.children:
                curr.children[ch] = TrieNode()
            curr = curr.children[ch]
        curr.is_end = True
    def search(self, word):
        curr = self.root
        for ch in word:
            if ch not in curr.children: return False
            curr = curr.children[ch]
        return curr.is_end
    def starts_with(self, prefix):
        curr = self.root
        for ch in prefix:
            if ch not in curr.children: return False
            curr = curr.children[ch]
        return True

